
document.addEventListener("DOMContentLoaded", function () {
  var botoesMenu = document.querySelectorAll("[data-bs-toggle='collapse']");
  botoesMenu.forEach(function (botao) {
    botao.addEventListener("click", function () {
      var seletorAlvo = botao.getAttribute("data-bs-target");
      var alvo = document.querySelector(seletorAlvo);
      if (alvo) {
        alvo.classList.toggle("show");
      }
    });
  });
});
